"""Thread-safe in-memory data store used as the source of truth."""
import itertools
import threading


class Store:
    def __init__(self):
        self._lock = threading.RLock()
        self._products = {}
        self._warehouses = {}
        self._stock_items = {}
        self._adjustments = {}
        self._thresholds = {}
        self._alerts = {}
        self._ids = {
            "product": itertools.count(1),
            "warehouse": itertools.count(1),
            "stock_item": itertools.count(1),
            "adjustment": itertools.count(1),
            "threshold": itertools.count(1),
            "alert": itertools.count(1),
        }

    def next_id(self, kind):
        with self._lock:
            return next(self._ids[kind])

    # Products
    def add_product(self, product):
        with self._lock:
            self._products[product.id] = product
            return product

    def get_product(self, product_id):
        return self._products.get(product_id)

    # Warehouses
    def add_warehouse(self, warehouse):
        with self._lock:
            self._warehouses[warehouse.id] = warehouse
            return warehouse

    def get_warehouse(self, warehouse_id):
        return self._warehouses.get(warehouse_id)

    # Stock items
    def add_stock_item(self, item):
        with self._lock:
            self._stock_items[item.id] = item
            return item

    def find_stock_item(self, product_id, warehouse_id):
        with self._lock:
            for item in self._stock_items.values():
                if item.product_id == product_id and item.warehouse_id == warehouse_id:
                    return item
            return None

    def list_stock_items(self):
        with self._lock:
            return list(self._stock_items.values())

    # Adjustments
    def add_adjustment(self, adj):
        with self._lock:
            self._adjustments[adj.id] = adj
            return adj

    # Thresholds
    def upsert_threshold(self, threshold):
        with self._lock:
            for existing in self._thresholds.values():
                if existing.product_id == threshold.product_id and existing.warehouse_id == threshold.warehouse_id:
                    existing.min_quantity = threshold.min_quantity
                    existing.updated_at = threshold.updated_at
                    return existing
            self._thresholds[threshold.id] = threshold
            return threshold

    def find_threshold(self, product_id, warehouse_id):
        with self._lock:
            for t in self._thresholds.values():
                if t.product_id == product_id and t.warehouse_id == warehouse_id:
                    return t
            return None

    # Alerts
    def add_alert(self, alert):
        with self._lock:
            self._alerts[alert.id] = alert
            return alert

    def get_alert(self, alert_id):
        return self._alerts.get(alert_id)

    def find_active_alert(self, product_id, warehouse_id):
        with self._lock:
            for a in self._alerts.values():
                if a.product_id == product_id and a.warehouse_id == warehouse_id and a.status == "ACTIVE":
                    return a
            return None

    def list_alerts(self):
        with self._lock:
            return list(self._alerts.values())

"""Core business logic for the inventory service."""
from datetime import datetime, timezone

from . import models
from .store import Store


def _now():
    return datetime.now(timezone.utc).isoformat()


class NotFoundError(Exception):
    pass


class ValidationError(Exception):
    pass


class ConflictError(Exception):
    pass


class InventoryService:
    def __init__(self, store=None):
        self.store = store or Store()

    # Products
    def create_product(self, sku, name, description=""):
        if not sku or not name:
            raise ValidationError("sku and name are required")
        pid = self.store.next_id("product")
        now = _now()
        product = models.Product(id=pid, sku=sku, name=name, description=description,
                                  created_at=now, updated_at=now)
        return self.store.add_product(product)

    def get_product(self, product_id):
        product = self.store.get_product(product_id)
        if not product:
            raise NotFoundError("product not found")
        return product

    # Warehouses
    def create_warehouse(self, code, name, location=""):
        if not code or not name:
            raise ValidationError("code and name are required")
        wid = self.store.next_id("warehouse")
        now = _now()
        warehouse = models.Warehouse(id=wid, code=code, name=name, location=location,
                                     created_at=now, updated_at=now)
        return self.store.add_warehouse(warehouse)

    def get_warehouse(self, warehouse_id):
        warehouse = self.store.get_warehouse(warehouse_id)
        if not warehouse:
            raise NotFoundError("warehouse not found")
        return warehouse

    # Stock
    def create_stock_item(self, product_id, warehouse_id, quantity=0):
        self.get_product(product_id)
        self.get_warehouse(warehouse_id)
        if quantity < 0:
            raise ValidationError("quantity cannot be negative")
        if self.store.find_stock_item(product_id, warehouse_id):
            raise ConflictError("stock item already exists")
        sid = self.store.next_id("stock_item")
        now = _now()
        item = models.StockItem(id=sid, product_id=product_id, warehouse_id=warehouse_id,
                                 quantity=quantity, reserved_quantity=0, version=1, updated_at=now)
        return self.store.add_stock_item(item)

    def get_stock(self, warehouse_id, product_id):
        item = self.store.find_stock_item(product_id, warehouse_id)
        if not item:
            raise NotFoundError("stock item not found")
        return item

    def list_stock(self, page=1, page_size=20):
        items = sorted(self.store.list_stock_items(), key=lambda i: i.id)
        total = len(items)
        start = (page - 1) * page_size
        end = start + page_size
        return items[start:end], total

    def adjust_stock(self, product_id, warehouse_id, delta, reason="", actor="system", correlation_id=None):
        item = self.store.find_stock_item(product_id, warehouse_id)
        if not item:
            raise NotFoundError("stock item not found")
        new_quantity = item.quantity + delta
        if new_quantity < 0:
            raise ValidationError("resulting quantity cannot be negative")
        item.quantity = new_quantity
        item.version += 1
        item.updated_at = _now()

        aid = self.store.next_id("adjustment")
        adjustment = models.StockAdjustment(
            id=aid, stock_item_id=item.id, delta=delta, resulting_quantity=new_quantity,
            reason=reason, actor=actor, correlation_id=correlation_id, created_at=_now())
        self.store.add_adjustment(adjustment)

        alert_triggered = self._evaluate_threshold(product_id, warehouse_id, new_quantity)
        return adjustment, item, alert_triggered

    def _evaluate_threshold(self, product_id, warehouse_id, quantity):
        threshold = self.store.find_threshold(product_id, warehouse_id)
        if threshold is None:
            threshold = self.store.find_threshold(product_id, None)
        if threshold is None:
            return False
        active = self.store.find_active_alert(product_id, warehouse_id)
        if quantity < threshold.min_quantity:
            if active:
                return False
            aid = self.store.next_id("alert")
            alert = models.Alert(id=aid, product_id=product_id, warehouse_id=warehouse_id,
                                  current_quantity=quantity, threshold_value=threshold.min_quantity,
                                  status="ACTIVE", created_at=_now())
            self.store.add_alert(alert)
            return True
        else:
            if active:
                active.status = "RESOLVED"
                active.resolved_at = _now()
                active.resolved_by = "system"
            return False

    # Thresholds
    def set_threshold(self, product_id, warehouse_id, min_quantity):
        self.get_product(product_id)
        if warehouse_id is not None:
            self.get_warehouse(warehouse_id)
        if min_quantity < 0:
            raise ValidationError("min_quantity cannot be negative")
        tid = self.store.next_id("threshold")
        now = _now()
        threshold = models.Threshold(id=tid, product_id=product_id, warehouse_id=warehouse_id,
                                      min_quantity=min_quantity, created_at=now, updated_at=now)
        return self.store.upsert_threshold(threshold)

    # Alerts
    def list_alerts(self, page=1, page_size=20, status=None):
        alerts = sorted(self.store.list_alerts(), key=lambda a: a.id)
        if status:
            alerts = [a for a in alerts if a.status == status]
        total = len(alerts)
        start = (page - 1) * page_size
        end = start + page_size
        return alerts[start:end], total

    def resolve_alert(self, alert_id, resolved_by="user"):
        alert = self.store.get_alert(alert_id)
        if not alert:
            raise NotFoundError("alert not found")
        if alert.status == "RESOLVED":
            raise ConflictError("alert already resolved")
        alert.status = "RESOLVED"
        alert.resolved_at = _now()
        alert.resolved_by = resolved_by
        return alert

"""WSGI REST API for the inventory service."""
import json
import re
from dataclasses import asdict
from urllib.parse import urlparse, parse_qs

from .service import InventoryService, NotFoundError, ValidationError, ConflictError

_STATUS_TEXT = {
    200: "OK", 201: "Created", 400: "Bad Request", 404: "Not Found",
    409: "Conflict", 500: "Internal Server Error",
}


def _to_dict(obj):
    return asdict(obj)


class InventoryAPI:
    def __init__(self, service=None):
        self.service = service or InventoryService()
        self.routes = [
            ("POST", re.compile(r"^/products$"), self.create_product),
            ("GET", re.compile(r"^/products/(?P<product_id>\d+)$"), self.get_product),
            ("POST", re.compile(r"^/warehouses$"), self.create_warehouse),
            ("GET", re.compile(r"^/warehouses/(?P<warehouse_id>\d+)$"), self.get_warehouse),
            ("POST", re.compile(r"^/stock/adjustments$"), self.adjust_stock),
            ("POST", re.compile(r"^/stock$"), self.create_stock),
            ("GET", re.compile(r"^/stock$"), self.list_stock),
            ("GET", re.compile(r"^/stock/(?P<warehouse_id>\d+)/(?P<product_id>\d+)$"), self.get_stock),
            ("PUT", re.compile(r"^/thresholds/(?P<product_id>\d+)/(?P<warehouse_id>\d+)$"), self.set_threshold),
            ("GET", re.compile(r"^/alerts$"), self.list_alerts),
            ("POST", re.compile(r"^/alerts/(?P<alert_id>\d+)/resolve$"), self.resolve_alert),
        ]

    def __call__(self, environ, start_response):
        method = environ.get("REQUEST_METHOD", "GET")
        path = urlparse(environ.get("PATH_INFO", "/")).path
        query = parse_qs(urlparse(environ.get("QUERY_STRING", "")).query)
        body = self._read_body(environ)
        for m, pattern, handler in self.routes:
            if m != method:
                continue
            match = pattern.match(path)
            if match:
                try:
                    status, payload = handler(match.groupdict(), query, body)
                except NotFoundError as e:
                    status, payload = 404, {"error": str(e)}
                except ValidationError as e:
                    status, payload = 400, {"error": str(e)}
                except ConflictError as e:
                    status, payload = 409, {"error": str(e)}
                except Exception as e:
                    status, payload = 500, {"error": str(e)}
                return self._respond(start_response, status, payload)
        return self._respond(start_response, 404, {"error": "not found"})

    def _read_body(self, environ):
        try:
            length = int(environ.get("CONTENT_LENGTH") or 0)
        except ValueError:
            length = 0
        if length <= 0:
            return {}
        raw = environ["wsgi.input"].read(length)
        if not raw:
            return {}
        return json.loads(raw.decode("utf-8"))

    def _respond(self, start_response, status, payload):
        body = json.dumps(payload).encode("utf-8")
        reason = _STATUS_TEXT.get(status, "OK")
        start_response(f"{status} {reason}", [("Content-Type", "application/json"),
                                                ("Content-Length", str(len(body)))])
        return [body]

    # Handlers
    def create_product(self, params, query, body):
        p = self.service.create_product(body.get("sku"), body.get("name"), body.get("description", ""))
        d = _to_dict(p)
        return 201, {"id": d["id"], "sku": d["sku"], "name": d["name"],
                     "description": d["description"], "created_at": d["created_at"]}

    def get_product(self, params, query, body):
        p = self.service.get_product(int(params["product_id"]))
        return 200, _to_dict(p)

    def create_warehouse(self, params, query, body):
        w = self.service.create_warehouse(body.get("code"), body.get("name"), body.get("location", ""))
        d = _to_dict(w)
        return 201, {"id": d["id"], "code": d["code"], "name": d["name"],
                     "location": d["location"], "created_at": d["created_at"]}

    def get_warehouse(self, params, query, body):
        w = self.service.get_warehouse(int(params["warehouse_id"]))
        return 200, _to_dict(w)

    def create_stock(self, params, query, body):
        item = self.service.create_stock_item(int(body.get("product_id")), int(body.get("warehouse_id")),
                                               int(body.get("quantity", 0)))
        d = _to_dict(item)
        return 201, {"id": d["id"], "product_id": d["product_id"], "warehouse_id": d["warehouse_id"],
                     "quantity": d["quantity"], "updated_at": d["updated_at"]}

    def adjust_stock(self, params, query, body):
        adjustment, item, triggered = self.service.adjust_stock(
            int(body.get("product_id")), int(body.get("warehouse_id")), int(body.get("delta")),
            body.get("reason", ""), body.get("actor", "system"), body.get("correlation_id"))
        return 201, {
            "adjustment_id": adjustment.id,
            "stock_item": {"product_id": item.product_id, "warehouse_id": item.warehouse_id,
                            "quantity": item.quantity},
            "alert_triggered": triggered,
        }

    def list_stock(self, params, query, body):
        page = int(query.get("page", ["1"])[0])
        page_size = int(query.get("page_size", ["20"])[0])
        items, total = self.service.list_stock(page, page_size)
        return 200, {
            "items": [{"product_id": i.product_id, "warehouse_id": i.warehouse_id,
                       "quantity": i.quantity, "reserved_quantity": i.reserved_quantity,
                       "updated_at": i.updated_at} for i in items],
            "total": total, "page": page, "page_size": page_size,
        }

    def get_stock(self, params, query, body):
        item = self.service.get_stock(int(params["warehouse_id"]), int(params["product_id"]))
        return 200, {"product_id": item.product_id, "warehouse_id": item.warehouse_id,
                      "quantity": item.quantity, "reserved_quantity": item.reserved_quantity,
                      "updated_at": item.updated_at}

    def set_threshold(self, params, query, body):
        t = self.service.set_threshold(int(params["product_id"]), int(params["warehouse_id"]),
                                        int(body.get("min_quantity")))
        return 200, {"product_id": t.product_id, "warehouse_id": t.warehouse_id,
                      "min_quantity": t.min_quantity, "updated_at": t.updated_at}

    def list_alerts(self, params, query, body):
        page = int(query.get("page", ["1"])[0])
        page_size = int(query.get("page_size", ["20"])[0])
        status = query.get("status", [None])[0]
        alerts, total = self.service.list_alerts(page, page_size, status)
        return 200, {
            "items": [{"id": a.id, "product_id": a.product_id, "warehouse_id": a.warehouse_id,
                       "current_quantity": a.current_quantity, "threshold_value": a.threshold_value,
                       "status": a.status, "created_at": a.created_at} for a in alerts],
            "total": total, "page": page, "page_size": page_size,
        }

    def resolve_alert(self, params, query, body):
        a = self.service.resolve_alert(int(params["alert_id"]), body.get("resolved_by", "user"))
        return 200, {"id": a.id, "status": a.status, "resolved_at": a.resolved_at,
                     "resolved_by": a.resolved_by}
